export class ProcessControlUnavailableError extends Error {}

export class ProcessControlClient {
  constructor(private readonly socketPath?: string) {}

  async status(): Promise<ProcessInfo[]> {
    const response = await this.request({ action: "status" });
    return response.processes as ProcessInfo[];
  }

  async restart(targets: string[]): Promise<RestartOperation> {
    const response = await this.request({ action: "restart", targets });
    return response.operation as RestartOperation;
  }

  async operation(id: string): Promise<RestartOperation> {
    const response = await this.request({ action: "operation", id });
    return response.operation as RestartOperation;
  }

  private async request(body: Record<string, unknown>): Promise<Record<string, unknown>> {
    const socketPath = this.socketPath;
    if (!socketPath) throw new ProcessControlUnavailableError("process control is not configured");
    return new Promise((resolve, reject) => {
      const socket = net.createConnection(socketPath);
      let output = "";
      const timer = setTimeout(() => { socket.destroy(); reject(new ProcessControlUnavailableError("process control did not respond")); }, 7_000);
      socket.setEncoding("utf8");
      socket.once("connect", () => socket.write(JSON.stringify(body) + "\n"));
      socket.on("data", (chunk: string) => {
        output += chunk;
        const newline = output.indexOf("\n");
        if (newline < 0) return;
        clearTimeout(timer);
        socket.end();
        try {
          const response = JSON.parse(output.slice(0, newline)) as { ok?: boolean; error?: string } & Record<string, unknown>;
          if (response.ok !== true) throw new Error(response.error ?? "process control rejected the request");
          resolve(response);
        } catch (error) { reject(error); }
      });
      socket.once("error", (error) => { clearTimeout(timer); reject(new ProcessControlUnavailableError(error.message)); });
    });
  }
}

